import { type Option, type Detail } from './interfaces';
/**
 * Builds a per-detail availability map from SKU-level data.
 *
 * Exported as a pure function so it can be unit-tested independently of the
 * Stencil component (the @State availabilityMap backing-store is not accessible
 * via page.rootInstance in the Stencil mock-doc test environment).
 *
 * Status values:
 *   'available'    – at least one in-stock SKU for this detail + current selections
 *   'out_of_stock' – all matching SKUs are out of stock
 *   'impossible'   – no SKU intersection exists for this combination
 *
 * skus_availability is always the authoritative source when present; is_out is
 * consulted only as a last resort when a detail has no SKU data at all.
 *
 * For unlimited products (no SKU data, or all SKUs false), all options default
 * to available unless explicitly marked as out of stock.
 *
 * @param isProductAvailable – whether product is available at the parent level
 *        (e.g., quantity > 0 or -1 for unlimited). If true and all SKUs are false,
 *        treat as available (data is incomplete or product is unlimited).
 */
export declare function computeAvailabilityMap(optionsData: Option[], selectedOptions: Array<Detail & {
    option_id: number | string;
}>, isProductAvailable?: boolean): Record<string | number, 'available' | 'out_of_stock' | 'impossible'>;
